entries[226357] = { ["name"] = "Diamond Mechsuit", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"These crystal-powered mechsuits are the epitome of Earthen Federation technology.\"\nAchievement:\nThe War Within Keystone Master: Season One\nCategory:\nDungeons" }
entries[226358] = { ["name"] = "Spare Venture Co. Uniform", ["text"] = "Quest Item\nUse: Put on a Venture Co. uniform, allowing you to talk to Venture Co. employees in the Heaps. Can only be used while near the area.\n\nIf you lose your uniform, you can put on another one at any time. (5 Sec Cooldown)\n\"Mostly fits you. Sort of.\"" }
