entries[226373] = { ["name"] = "Everlasting Noggenfogger Elixir", ["text"] = "Binds when picked up\nUnique\nToy\nUse: The mouthfeel of oil and the brininess of an oyster. Delicious.\n\nCosts 50 silver per gulp. (3 Sec Cooldown)\nRequires Revered reputation with the Steamwheedle Cartel in Undermine.\n\"The color, the smell, the transformations! This elixir is what bards speak of when regaling crowds with tales of the ambrosia of the goblins.\"\nSell Price:" }
