entries[226505] = { ["name"] = "Nerubian Gemweaver", ["text"] = "Binds when picked up\nUse: Add a socket to a War Within Season 1 item that does not already have one. Can be used on Helms, Bracers, or Belts. Cannot be used on PvP equipment." }
entries[226506] = { ["name"] = "Hand of Reshkigaal", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Reshkigaal bided her time as her kin each tried their hand at usurping the Banished One. She sought to attack when he was distracted, but the Jailer's spies had been tracking her. With their warning and aid, the Jailer prevailed.\"\nTrading Post" }
entries[226507] = { ["name"] = "Venom Dahn's Webscrub", ["text"] = "Binds when picked up\nUse: Scrub yourself down with skitterling venom to remove a single stack of Eradicator's Mark.\nRequires Crony reputation with the General.\n\"A venom-base body scrub to remove grime & web build up from Eradicator's Marks. 88% natural flavors!\"" }
entries[226508] = { ["name"] = "Vizier's Influence", ["text"] = "Binds when picked up\nUse: You've bribed the right nerubians.\n\nNext time the guards would kick you from the City of Threads, you'll be sent to the Royal Apothecary instead. This effect will last for 60 minutes.\nRequires Accomplice reputation with the Vizier.\n\"A set of \"official\" paperwork. \"Encourages\" guards in the City of Threads to redirect you to the Royal Apothecary when captured.\"" }
entries[226509] = { ["name"] = "General's Insight", ["text"] = "Binds when picked up\nUse: You can visualize the detection radius of guards in the City of Threads for 10 minutes.\n\nYou've learned much from the General.\nRequires Accomplice reputation with the General.\n\"A copy of Sureki patrols and methods. Allows you to see the detection radius for all guards in the City of Threads.\"" }
entries[226510] = { ["name"] = "Weaver's Facade", ["text"] = "Binds when picked up\nUse: You assume the visage of a trueform nerubian. Guards in the City of Threads will have a reduced detection radius for 1 minute.\n\nThe Weaver is a master of disguises.\nRequires Accomplice reputation with the Weaver.\n\"A pheromonal concoction to fool guards in the City of Threads, significantly reducing their detection radius. A Weaver's specialty.\"" }
entries[226511] = { ["name"] = "Nerubimorph Poultice", ["text"] = "Binds when picked up\nUse: Lob a concoction to transform a guard in the City of Threads into a less threatening form for 30 Seconds.\n\nA signature brew of the Vizier himself.\nRequires Crony reputation with the Vizier.\nRequires Crony reputation with the Weaver.\n\"A throwable concoction that transforms victims into harmless weave-rats for a short duration. Only works on guards in the City of Threads.\"" }
entries[226512] = { ["name"] = "Treasure Map: Forgotten Memorial", ["text"] = "Binds when picked up\nUnique (5)\nUse: Reveal the location of a Forgotten Memorial on your map.\nRequires Crony reputation with the General." }
entries[226513] = { ["name"] = "Treasure Map: Kaheti Excavation", ["text"] = "Binds when picked up\nUnique (5)\nUse: Reveal the location of a Kaheti Excavation on your map.\nRequires Crony reputation with the Vizier." }
entries[226514] = { ["name"] = "Treasure Map: Weave-Rat Cache", ["text"] = "Binds when picked up\nUnique (5)\nUse: Reveal the location of a Weave-Rat Cache on your map.\nRequires Crony reputation with the Weaver." }
entries[226515] = { ["name"] = "Rumor Map: Bounties", ["text"] = "Binds when picked up\nUnique (5)\nUse: Reveal the location of a Bounty Rumor on your map." }
entries[226516] = { ["name"] = "Rumor Map: Disruption", ["text"] = "Binds when picked up\nUnique (5)\nUse: Reveal the location of a Disruption Rumor on your map." }
entries[226517] = { ["name"] = "Rumor Map: Espionage", ["text"] = "Binds when picked up\nUnique (5)\nUse: Reveal the location of a Espionage Rumor on your map." }
entries[226518] = { ["name"] = "Phero-Escape", ["text"] = "Binds when picked up\nUse: Throw an implosion of various pheromones to stun guards in the City of Threads for 2 seconds, breaking you from combat.\nRequires Crony reputation with the Vizier.\n\"Throw this implosion of pheromones to stun enemies and disengage from combat. Only works on guards in the City of Threads.\"" }
entries[226519] = { ["name"] = "General's Expertise", ["text"] = "Binds when picked up\nToy\nUse: You can visualize the detection radius of guards in the City of Threads.\n\nYou've learned much from the General.\nRequires Crony reputation with either the Weaver, the General, or the Vizier.\n\"A transcribed copy of the combat manual all soldiers in Azj-Kahet study from. When active, allows you to see the detection radius for all guards in the City of Threads.\"" }
entries[226520] = { ["name"] = "Queen's Pheromone", ["text"] = "Binds when picked up\nUse: The pheromones of the Queen.\n\nGuards in the City of Threads will no longer interfere with you.\nRequires Mastermind reputation with either the Weaver, the General, or the Vizier.\n\"The pheromones of the Queen. Obtained discreetly. Guards in the City of Threads will no longer be able to detect you.\"" }
entries[226521] = { ["name"] = "Reinforced Wax Plating", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+389 [Agility or Strength]\nEquip: Apply a thick coating of reinforced wax to your armor, granting you 1922 damage reduction.\nSell Price:" }
entries[226522] = { ["name"] = "Demolition Controller Fragment", ["text"] = "Quest Item\n\"There's some grains of sand caught in the wires.\"" }
entries[226524] = { ["name"] = "Partially-Charged Hologem", ["text"] = "Races: Draenei , Lightforged Draenei\nUse: Activate the hologem. (30 Sec Cooldown)\n\"Just enough power remaining to be used for a short time.\"\nSell Price:" }
entries[226525] = { ["name"] = "Demolition Control Code", ["text"] = "Quest Item" }
entries[226539] = { ["name"] = "Scroll of Momentum", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+389 Agility\nEquip: Your harmful attacks and abilities have a high chance to build momentum, granting 2% bonus movement speed per stack.\n\nAt 5 stacks you reach full momentum increasing your movement speed bonus to 20% for 10 sec. While at full momentum, your attacks hit the target at high velocity dealing an additional ( 1 * 2869 ) Nature damage scaling up with your current movement speed. (500ms cooldown)\nSell Price:" }
entries[226643] = { ["name"] = "Plans: Beledar's Bulwark", ["text"] = "Use: Teaches you how to craft Beledar's Bulwark.\nRequires Khaz Algar Blacksmithing (35)\nSell Price:" }
entries[226672] = { ["name"] = "Band of Elemental Chaos", ["text"] = "Binds when picked up\nUnique-Equipped\nFinger\n+636 Stamina\n+ 751 Versatility\n+ 563 Mastery\nSell Price:" }
entries[226681] = { ["name"] = "Sizzling Cinderpollen", ["text"] = "\"Causes particularly painful sneezing fits. The meadery has stockpiled quite a bit now thanks to your efforts.\"\nSell Price:" }
entries[226683] = { ["name"] = "Malfunctioning Mechsuit", ["text"] = "Binds when picked up\nThis Item Begins a Quest\n\"A machine that has lost its proper form.\"" }
