entries[226695] = { ["name"] = "Cunning Advisor's Favor", ["text"] = "Binds when picked up\nNeck\n+5,034 Stamina\n+ 2,689 Versatility\n+ 556 Mastery\n\"Anub'arash wouldn't know wisdom if it stormed the palace! Now, how to get rid of him...\"\nSell Price:" }
entries[226696] = { ["name"] = "Mighty Advisor's Favor", ["text"] = "Binds when picked up\nNeck\n+5,034 Stamina\n+ 2,689 Versatility\n+ 556 Mastery\n\"Here's some wisdom for you, Takazj: Stay out of my way.\"\nSell Price:" }
