entries[228820] = { ["name"] = "Antonidas' Introduction to Arcane Magic", ["text"] = "Quest Item\n\"A primer on magic penned by the esteemed Archmage Antonidas, it offers novices a comprehensive guide to the mage principles, spells, and the history of arcane magic. This tome is an essential one for aspiring mages.\"" }
