entries[228921] = { ["name"] = "Griftah's Heavy-Duty Embellishing Powder", ["text"] = "Optional Crafting Reagent\n\nProvides the following property: Grant your crafted equipment a completely imperceivable but totally real improvement.\nUsable with: Khaz Algar recipes for most unembellished equipment.\n\"Guaranteed to make your equipment outshine any previous embellishments it might have had. Can be bought and sold on the Auction House.\"\nSell Price:" }
