entries[228940] = { ["name"] = "Notorious Thread's Hearthstone", ["text"] = "Binds when picked up\nUnique\nToy\nUse: Returns you to Hearthstone Location. Speak to an Innkeeper in a different place to change your home location.\n\nCan only be used by those who've proven themselves to the Severed Threads.\nRequires Mastermind reputation with either the Weaver, the General, or the Vizier.\n\"Return home with the aid of your Severed Threads patrons.\"" }
entries[228941] = { ["name"] = "Inert Peculiar Key", ["text"] = "Secrets of Azeroth\nBinds when picked up\nUse: Socket a gem into the key.\n\"A battered old key. It appears to have a socket for something.\"" }
entries[228942] = { ["name"] = "Bountiful Coffer", ["text"] = "Requires level 70 to 80 ( 80)\n\"Contains powerful equipment, a radiant echo, bonus currencies, and a chance at a new or upgraded curio. Requires a Restored Coffer Key to open.\"" }
entries[228943] = { ["name"] = "Spymaster's Severed Thread", ["text"] = "Binds when picked up\nUnique\nUse: Adds a cosmetic flair from the Weaver when using your Notorious Threads' Hearthstone.\nRequires Mastermind reputation with the Weaver.\n\"The Weaver sends her highest regards.\"" }
